(308407, 22497, 7969, '<td valign="top">I like your idea, just wish the white part of frame wasn''t  SO white, I find it distracting a little.</td>', 'I like your idea, just wish the white part of frame wasn''t  SO white, I find it distracting a little.', '2003-05-28 01:12:01.000000', NULL, 1),
(308415, 22891, 7969, '<td valign="top">Technically flawless from what i can see.</td>', 'Technically flawless from what i can see.', '2003-05-28 01:16:07.000000', NULL, 1),
(308422, 23012, 7969, '<td valign="top">Creative shot idea.</td>', 'Creative shot idea.', '2003-05-28 01:21:08.000000', NULL, 1),
(308423, 23056, 3419, '<td valign="top">The lighting is beautiful, but the photo is too soft overall. Would prefer crisper detail. I love the saturated colors.</td>', 'The lighting is beautiful, but the photo is too soft overall. Would prefer crisper detail. I love the saturated colors.', '2003-05-28 01:21:53.000000', NULL, 1),
(308427, 22961, 7969, '<td valign="top">Wow were you in the right spot at right time. I love herons and never saw a baby.  thank you for the chance.</td>', 'Wow were you in the right spot at right time. I love herons and never saw a baby.  thank you for the chance.', '2003-05-28 01:26:54.000000', NULL, 1),
(308429, 22888, 6900, '<td valign="top">Best picture I''ve seen in the challenge so far.  Nice job.</td>', 'Best picture I''ve seen in the challenge so far.  Nice job.', '2003-05-28 01:28:06.000000', NULL, 1),
(308431, 22958, 7920, '<td valign="top">Everything about this is perfect as far as I can tell.  Not to mention, an adorable subject.  I wish I could give you more than 10!  =)</td>', 'Everything about this is perfect as far as I can tell.  Not to mention, an adorable subject.  I wish I could give you more than 10!  =)', '2003-05-28 01:29:46.000000', NULL, 1),
