(308433, 22891, 7920, '<td valign="top">LOL</td>', 'LOL', '2003-05-28 01:30:44.000000', NULL, 1),
(308434, 22880, 7969, '<td valign="top">I like your use of ''extreme effect" of contrast or sharp-- not sure which.  But would have  cropped a little more of foeground.</td>', 'I like your use of ''extreme effect" of contrast or sharp-- not sure which.  But would have  cropped a little more of foeground.', '2003-05-28 01:30:47.000000', NULL, 1),
