(309862, 22896, 7570, '<td valign="top">this look like a local shot....hmmm</td>', 'this look like a local shot....hmmm', '2003-05-29 04:26:59.000000', NULL, 1),
(309864, 22907, 2079, '<td valign="top">I love your crop on this shot. I think it leaves the "who is this" thought in the mind of the viewer. It could be any one we know. I rarely show the faces of the homeless in my work. Im sure you will get a few negative comments for this crop, but I think it adds volumes to this shot. - Good Luck - 8</td>', 'I love your crop on this shot. I think it leaves the "who is this" thought in the mind of the viewer. It could be any one we know. I rarely show the faces of the homeless in my work. Im sure you will get a few negative comments for this crop, but I think it adds volumes to this shot. - Good Luck - 8', '2003-05-29 04:34:01.000000', NULL, 1),
(309870, 23006, 8472, '<td valign="top">Is it just me or is it slightly out of focus? It coud just be the 3rd guinness I drank. This could be a winning photograph but theres just something not quite right... I can quite put my finger on it, maybe it''s the lighting thats a bit sharp, or the background is too neutral... I''m not sure... <br/> <br/>I can tell you with some authority the antialiasing is not working too well, theres a thin red line at the bottom of the shell, and a blue one at the top of the leaf. If you are shooting at a medium resolution, Take it up a notch and drop it down to screen size in photoshop rather thatn sooting at screen size. That should clear up the odd lines. If you are already doing thnat then there;s not much else you can do that wouldn''t go against DP rules.</td>', 'Is it just me or is it slightly out of focus? It coud just be the 3rd guinness I drank. This could be a winning photograph but theres just something not quite right... I can quite put my finger on it, maybe it''s the lighting thats a bit sharp, or the background is too neutral... I''m not sure...  I can tell you with some authority the antialiasing is not working too well, theres a thin red line at the bottom of the shell, and a blue one at the top of the leaf. If you are shooting at a medium resolution, Take it up a notch and drop it down to screen size in photoshop rather thatn sooting at screen size. That should clear up the odd lines. If you are already doing thnat then there;s not much else you can do that wouldn''t go against DP rules.', '2003-05-29 04:59:05.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(309871, 22907, 8472, '<td valign="top">A clever concept and daring photo!</td>', 'A clever concept and daring photo!', '2003-05-29 04:59:51.000000', NULL, 1),
(309872, 23019, 8472, '<td valign="top">Nice clouds. How did you do that? Circular Polarizer?</td>', 'Nice clouds. How did you do that? Circular Polarizer?', '2003-05-29 05:01:20.000000', NULL, 1),
(309873, 22999, 8472, '<td valign="top">beautiful colour, and a fairly balanced composure. The green bush on the right draws my attention a bit. I appreciate the reflection you put into the window.</td>', 'beautiful colour, and a fairly balanced composure. The green bush on the right draws my attention a bit. I appreciate the reflection you put into the window.', '2003-05-29 05:03:33.000000', NULL, 1),
(309874, 22373, 7369, '<td valign="top">I think there is too much barrel distortion in the picture. Also you could have shown us the real house and not a paiting. Not very interesting.</td>', 'I think there is too much barrel distortion in the picture. Also you could have shown us the real house and not a paiting. Not very interesting.', '2003-05-29 05:05:06.000000', NULL, 1),
(309875, 22801, 8472, '<td valign="top">There are filters you can but that may reduce the amount of reflection from the window. For a digital auto focus camera you need a circular polarizer. They are also usefull for taking shots over water, when you need to resuce glare.</td>', 'There are filters you can but that may reduce the amount of reflection from the window. For a digital auto focus camera you need a circular polarizer. They are also usefull for taking shots over water, when you need to resuce glare.', '2003-05-29 05:06:51.000000', NULL, 1),
(309876, 22991, 7369, '<td valign="top">Next time try not to use the flash, but try to use a longer exposure time. That way the colors and the light will be much better. For now the light is too harsh.</td>', 'Next time try not to use the flash, but try to use a longer exposure time. That way the colors and the light will be much better. For now the light is too harsh.', '2003-05-29 05:07:49.000000', NULL, 1),
(309877, 23036, 8472, '<td valign="top">Vancouver?</td>', 'Vancouver?', '2003-05-29 05:08:24.000000', NULL, 1),
(309878, 23014, 7369, '<td valign="top">Lovely composition and a nice way to meet the challenge!</td>', 'Lovely composition and a nice way to meet the challenge!', '2003-05-29 05:08:26.000000', NULL, 1),
(309879, 22822, 8472, '<td valign="top">you missed a comma on line 23.</td>', 'you missed a comma on line 23.', '2003-05-29 05:09:57.000000', NULL, 1),
(309880, 22282, 7369, '<td valign="top">The light is too harsh. Next time try to take the picture at another time; early morning or during sunset. Your photo will improve greatly that way.</td>', 'The light is too harsh. Next time try to take the picture at another time; early morning or during sunset. Your photo will improve greatly that way.', '2003-05-29 05:10:19.000000', NULL, 1),
(309882, 23013, 8472, '<td valign="top">Nice. the attention to detail is great. the post production was excecuted pefectly (according to my monitor). The sky could have been more dynamic, but ma nature just wasn\''t in your favour today.</td>', 'Nice. the attention to detail is great. the post production was excecuted pefectly (according to my monitor). The sky could have been more dynamic, but ma nature just wasn\''t in your favour today.', '2003-05-29 05:14:02.000000', NULL, 1),
(309883, 22365, 8472, '<td valign="top">Are there brick houses on the right?</td>', 'Are there brick houses on the right?', '2003-05-29 05:15:39.000000', NULL, 1),
(309884, 22875, 8472, '<td valign="top">or a sharp D</td>', 'or a sharp D', '2003-05-29 05:16:18.000000', NULL, 1),
