(310220, 22789, 6663, '<td valign="top">I''m afraid I''m not too keen on the border for this one - apart from that, hits the challenge, which was quite a toughie this week IMO.</td>', 'I''m afraid I''m not too keen on the border for this one - apart from that, hits the challenge, which was quite a toughie this week IMO.', '2003-05-29 15:12:57.000000', NULL, 1),
(310223, 22849, 6663, '<td valign="top">I like the way you''ve caught the kid''s eyes just in the background - you wouldn''t pick them out without really looking at the shot first, but they really make this pic. Nice.</td>', 'I like the way you''ve caught the kid''s eyes just in the background - you wouldn''t pick them out without really looking at the shot first, but they really make this pic. Nice.', '2003-05-29 15:14:17.000000', NULL, 1),
(310225, 22475, 6663, '<td valign="top">I like the position from which this shot has been taken - frames the whole thing very nicely.</td>', 'I like the position from which this shot has been taken - frames the whole thing very nicely.', '2003-05-29 15:16:03.000000', NULL, 1),
(310228, 22694, 6663, '<td valign="top">She looks at peace - I guess that''s the fairest way to judge this week''s challenge. The b&amp;w makes it a little poignant. Good shot.</td>', 'She looks at peace - I guess that''s the fairest way to judge this week''s challenge. The b&w makes it a little poignant. Good shot.', '2003-05-29 15:18:06.000000', NULL, 1),
(310231, 23006, 6663, '<td valign="top">Cracking shot - not sure the title /really/ relates to the pic but it''s certainly a very good photo on its own. The way the light''s reflecting off the little fella works very well. Good work.</td>', 'Cracking shot - not sure the title /really/ relates to the pic but it''s certainly a very good photo on its own. The way the light''s reflecting off the little fella works very well. Good work.', '2003-05-29 15:20:20.000000', NULL, 1),
(310233, 22250, 6663, '<td valign="top">I guess a lot of people are going to miss out on the lava lamp reference.</td>', 'I guess a lot of people are going to miss out on the lava lamp reference.', '2003-05-29 15:20:54.000000', NULL, 1),
(310234, 22616, 6663, '<td valign="top">Now who took this...? Unless that inscription is deliberately misleading.....</td>', 'Now who took this...? Unless that inscription is deliberately misleading.....', '2003-05-29 15:21:55.000000', NULL, 1),
(310236, 23011, 6663, '<td valign="top">Unbelievable range of colour you''ve caught in the sky here.</td>', 'Unbelievable range of colour you''ve caught in the sky here.', '2003-05-29 15:22:30.000000', NULL, 1),
(310238, 22846, 6663, '<td valign="top">Interesting idea - a bit different. Nice thinking.</td>', 'Interesting idea - a bit different. Nice thinking.', '2003-05-29 15:23:23.000000', NULL, 1),
(310240, 23028, 6663, '<td valign="top">Irony - 10. Seeing another pic of a flower, especially seemingly deliberately against the challenge - 0. Overall - 5.</td>', 'Irony - 10. Seeing another pic of a flower, especially seemingly deliberately against the challenge - 0. Overall - 5.', '2003-05-29 15:25:19.000000', NULL, 1),
(310242, 22877, 6663, '<td valign="top">Like the way you''ve framed the photo in the same colour as the painting - very clever effect. However, the fact that the main interest in this shot is another picture isn''t great - feels uncreative. But I do like the picture, so you save yourself with your taste in paintings :) Who''s it by? Quirky.</td>', 'Like the way you''ve framed the photo in the same colour as the painting - very clever effect. However, the fact that the main interest in this shot is another picture isn''t great - feels uncreative. But I do like the picture, so you save yourself with your taste in paintings :) Who''s it by? Quirky.', '2003-05-29 15:28:30.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(310243, 22995, 6663, '<td valign="top">Very original take on the ''home'' theme - I didn''t think of that one! (then again I''m English...)</td>', 'Very original take on the ''home'' theme - I didn''t think of that one! (then again I''m English...)', '2003-05-29 15:31:44.000000', NULL, 1),
(310245, 22489, 6663, '<td valign="top">Very nice shot indeed. I can\''t quite place my finger on what it is, but there\''s something very satisfying about looking at it. Perhaps the rows of houses, the birds, the bands of blues at the back...who knows? I just like it. The title helps - kinda stirring.<br/> <br/>Good to see you got the Milennium Monstrosity in there too :)</td>', 'Very nice shot indeed. I can\''t quite place my finger on what it is, but there\''s something very satisfying about looking at it. Perhaps the rows of houses, the birds, the bands of blues at the back...who knows? I just like it. The title helps - kinda stirring. Good to see you got the Milennium Monstrosity in there too :)', '2003-05-29 15:33:50.000000', NULL, 1),
(310246, 22891, 5364, '<td valign="top">I think I might have cropped this a little differently, a fraction off the left to loose the telegraph pole, and crop off the small building on the right. Otherwise I kike this picture.</td>', 'I think I might have cropped this a little differently, a fraction off the left to loose the telegraph pole, and crop off the small building on the right. Otherwise I kike this picture.', '2003-05-29 15:34:21.000000', NULL, 1),
(310250, 22621, 6663, '<td valign="top">Nice work - like the perspective. You''ve chosen a good position from which to shoot.</td>', 'Nice work - like the perspective. You''ve chosen a good position from which to shoot.', '2003-05-29 15:38:54.000000', NULL, 1),
(310251, 22512, 6663, '<td valign="top">Some shots just make you say ''wow'' when you see them. This is one of those. Great work - an unprecedented second 10 for me for the week. The best of luck to you - hope to see this place very high indeed.</td>', 'Some shots just make you say ''wow'' when you see them. This is one of those. Great work - an unprecedented second 10 for me for the week. The best of luck to you - hope to see this place very high indeed.', '2003-05-29 15:40:48.000000', NULL, 1),
(310252, 22896, 6663, '<td valign="top">Great clarity - beautiful bright colours.</td>', 'Great clarity - beautiful bright colours.', '2003-05-29 15:41:20.000000', NULL, 1),
(310253, 22992, 6663, '<td valign="top">:)</td>', ':)', '2003-05-29 15:42:33.000000', NULL, 1),
(310254, 22916, 6663, '<td valign="top">I think you should try and make future entries larger than this.</td>', 'I think you should try and make future entries larger than this.', '2003-05-29 15:44:01.000000', NULL, 1),
(310261, 22823, 6663, '<td valign="top">too much green!!!!!!! Try desaturating this a bit and it''d work quite nicely. As it is - overloads the eyes a little.</td>', 'too much green!!!!!!! Try desaturating this a bit and it''d work quite nicely. As it is - overloads the eyes a little.', '2003-05-29 15:53:23.000000', NULL, 1),
(310263, 23056, 6504, '<td valign="top">I think this would be a better picture if things were in focus, but the softness looks good too, gives it the softness of the sunset.  I would like to see a part of the house in this photo.</td>', 'I think this would be a better picture if things were in focus, but the softness looks good too, gives it the softness of the sunset.  I would like to see a part of the house in this photo.', '2003-05-29 15:55:09.000000', NULL, 1),
(310264, 22717, 6663, '<td valign="top">Great pun. The best ''home is where the [xxx] is'' this week. :)</td>', 'Great pun. The best ''home is where the [xxx] is'' this week. :)', '2003-05-29 15:56:59.000000', NULL, 1),
(310265, 22888, 6663, '<td valign="top">Clever. A reverse of what a lot of people have done, which is change the line to fit their home - you changed the map! :) Like it.</td>', 'Clever. A reverse of what a lot of people have done, which is change the line to fit their home - you changed the map! :) Like it.', '2003-05-29 16:00:16.000000', NULL, 1),
(310266, 22822, 6663, '<td valign="top">I feel for you. I''m currently revising for a Networking exam at university - this stuff is killing me.</td>', 'I feel for you. I''m currently revising for a Networking exam at university - this stuff is killing me.', '2003-05-29 16:01:42.000000', NULL, 1),
(310300, 22508, 8060, '<td valign="top">Best Interpretation ive seen so far. 10</td>', 'Best Interpretation ive seen so far. 10', '2003-05-29 16:28:45.000000', NULL, 1),
(310303, 22694, 3569, '<td valign="top">Very cute. Definitely at home.</td>', 'Very cute. Definitely at home.', '2003-05-29 16:30:18.000000', NULL, 1),
(310314, 23069, 8060, '<td valign="top">Good perception of this challenge, sinister, yet your reality not a cosy, safe interpretation . Except i think a different angle would have made better composistion. 10 for interpretation</td>', 'Good perception of this challenge, sinister, yet your reality not a cosy, safe interpretation . Except i think a different angle would have made better composistion. 10 for interpretation', '2003-05-29 16:36:32.000000', NULL, 1),
(310317, 23022, 8488, '<td valign="top">5. Fits the theme well enough, and there are no blatant ''you suck!'' flaws to it, but neither does it really grab me for any reason at all. For reasons of composition, cropping, or subject choice, it''s just a photo, and doesn''t do especially much for me, aesthetically.<br/> <br/>I do like the colors on the building, but the overall tone of the photo seems artificially dark (maybe to keep the sky from being blown out?), as if I''m viewing it through smoky cellophane. Probably due to your lens, the nominally vertical lines of the traffic signal and corner of the building lean to the right as they go up, giving it a slightly vertiginous feel.</td>', '5. Fits the theme well enough, and there are no blatant ''you suck!'' flaws to it, but neither does it really grab me for any reason at all. For reasons of composition, cropping, or subject choice, it''s just a photo, and doesn''t do especially much for me, aesthetically. I do like the colors on the building, but the overall tone of the photo seems artificially dark (maybe to keep the sky from being blown out?), as if I''m viewing it through smoky cellophane. Probably due to your lens, the nominally vertical lines of the traffic signal and corner of the building lean to the right as they go up, giving it a slightly vertiginous feel.', '2003-05-29 16:37:11.000000', NULL, 1),
(310321, 22373, 7350, '<td valign="top">Crooked and dark, with a flash reflection.  A good idea, but not very well executed, it seems to me.</td>', 'Crooked and dark, with a flash reflection.  A good idea, but not very well executed, it seems to me.', '2003-05-29 16:38:06.000000', NULL, 1),
(310322, 22888, 8060, '<td valign="top">good original perception of challenge. 8</td>', 'good original perception of challenge. 8', '2003-05-29 16:38:46.000000', NULL, 1),
(310324, 22404, 7350, '<td valign="top">For some reason I really like the composition here, with the only exception being what appears to be a small table in the lower right.  I think I''d like to be able to see it better or not at all.  Preferably, not at all, I think.  Still, 7.</td>', 'For some reason I really like the composition here, with the only exception being what appears to be a small table in the lower right.  I think I''d like to be able to see it better or not at all.  Preferably, not at all, I think.  Still, 7.', '2003-05-29 16:39:27.000000', NULL, 1),
(310325, 22983, 8488, '<td valign="top">5. Fits the theme well enough, and there are no blatant ''you suck!'' flaws to it, but neither does it really grab me for any reason at all. For reasons of composition, cropping, or subject choice, it''s just a photo, and doesn''t do especially much for me, aesthetically. It''s, uhm, kind of boring. It does look a little like it''d fit right in in a corner of an article in Better Homes and Gardens, or some other interior design magazine, though.<br/> <br/>The color and lighting are nice, and I also like hwo the vase is set at the point where the tabletop''s lines converge, but there''s really no central thing-to-look-at. The vase might have been central, but it''s been arranged far down in a corner, with glare that distracts from its own very busy pattern. The sofas might be, but the lighting makes them fade into the background, largely. The lamp and picture are both off-center enough and unlit enough to not quite be focal points either.</td>', '5. Fits the theme well enough, and there are no blatant ''you suck!'' flaws to it, but neither does it really grab me for any reason at all. For reasons of composition, cropping, or subject choice, it''s just a photo, and doesn''t do especially much for me, aesthetically. It''s, uhm, kind of boring. It does look a little like it''d fit right in in a corner of an article in Better Homes and Gardens, or some other interior design magazine, though. The color and lighting are nice, and I also like hwo the vase is set at the point where the tabletop''s lines converge, but there''s really no central thing-to-look-at. The vase might have been central, but it''s been arranged far down in a corner, with glare that distracts from its own very busy pattern. The sofas might be, but the lighting makes them fade into the background, largely. The lamp and picture are both off-center enough and unlit enough to not quite be focal points either.', '2003-05-29 16:39:36.000000', NULL, 1),
(310326, 23012, 7350, '<td valign="top">Is this shot upside down, in the hood of a car?</td>', 'Is this shot upside down, in the hood of a car?', '2003-05-29 16:40:36.000000', NULL, 1),
(310327, 22939, 8488, '<td valign="top">5. Fits the theme well enough, and there are no blatant ''you suck!'' flaws to it, but neither does it really grab me for any reason at all. For reasons of composition, cropping, or subject choice, it''s just a photo, and doesn''t do especially much for me, aesthetically.<br/> <br/>The similarity of color of tree and sky tends to make the trunks and the glow blend into each other, strangely, and the overbright under-the-overhang areas both rivet the attention and then shove you away with their lack fo detail. IF it were about either of the trees, framed to put them in the center, compositionally, it might be a more interesting shot. If it were about either of the houses, likewise a different framing would have worked better.</td>', '5. Fits the theme well enough, and there are no blatant ''you suck!'' flaws to it, but neither does it really grab me for any reason at all. For reasons of composition, cropping, or subject choice, it''s just a photo, and doesn''t do especially much for me, aesthetically. The similarity of color of tree and sky tends to make the trunks and the glow blend into each other, strangely, and the overbright under-the-overhang areas both rivet the attention and then shove you away with their lack fo detail. IF it were about either of the trees, framed to put them in the center, compositionally, it might be a more interesting shot. If it were about either of the houses, likewise a different framing would have worked better.', '2003-05-29 16:41:05.000000', NULL, 1),
(310329, 23063, 7350, '<td valign="top">You wish...</td>', 'You wish...', '2003-05-29 16:42:07.000000', NULL, 1),
(310331, 22477, 8488, '<td valign="top">5. Fits the theme well enough, and there are no blatant ''you suck!'' flaws to it, but neither does it really grab me for any reason at all. For reasons of composition, cropping, or subject choice, it''s just a photo, and doesn''t do especially much for me, aesthetically.<br/> <br/>The way you''ve got it cropped, it''s almost about the *grass* ... which is a very odd choice. The house itself is a nice subject, and nestles neatly behind the hill, but the picture as a whole isn''t about any one thing (as I look at it, anyway). Good colors; a bit better focus on the house might also have directed there attention better.</td>', '5. Fits the theme well enough, and there are no blatant ''you suck!'' flaws to it, but neither does it really grab me for any reason at all. For reasons of composition, cropping, or subject choice, it''s just a photo, and doesn''t do especially much for me, aesthetically. The way you''ve got it cropped, it''s almost about the *grass* ... which is a very odd choice. The house itself is a nice subject, and nestles neatly behind the hill, but the picture as a whole isn''t about any one thing (as I look at it, anyway). Good colors; a bit better focus on the house might also have directed there attention better.', '2003-05-29 16:42:47.000000', NULL, 1),
