INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(310891, 23003, 8060, '<td valign="top">reminds me of the shop ''Paperchase'', good clear image.</td>', 'reminds me of the shop ''Paperchase'', good clear image.', '2003-05-30 13:10:33.000000', NULL, 1),
(310894, 23013, 8060, '<td valign="top">i cant think of a relevant comment to make but i really like it. Even though the powerstation (or whatever it is) it makes an attractive image. 10</td>', 'i cant think of a relevant comment to make but i really like it. Even though the powerstation (or whatever it is) it makes an attractive image. 10', '2003-05-30 13:12:45.000000', NULL, 1),
(310947, 23027, 3540, '<td valign="top">By far the best title in the challenge.  This one really made me laugh.  I have 5 cats, so I know how you feel.  Only one goes outside at all though.  But I swear they think they own the place.  I like the way you framed this and that the mouth isn''t showing all the way.   Good job with the DOF and the picture is crystal clear.  Nice work</td>', 'By far the best title in the challenge.  This one really made me laugh.  I have 5 cats, so I know how you feel.  Only one goes outside at all though.  But I swear they think they own the place.  I like the way you framed this and that the mouth isn''t showing all the way.   Good job with the DOF and the picture is crystal clear.  Nice work', '2003-05-30 15:45:27.000000', NULL, 1),
(310948, 22883, 3540, '<td valign="top">I''m not so sure of this shot for this challenge, but I''ll tell you it is a great shot.  really clear with a shallow DOF makes this picture.  The little shine off the spider is really cool too.  Very nice picture even though I don''t think its really good for this challenge.  Maybe an allusion to this being the spider''s home would''ve been a little more appropriate.  Great photo regardless!</td>', 'I''m not so sure of this shot for this challenge, but I''ll tell you it is a great shot.  really clear with a shallow DOF makes this picture.  The little shine off the spider is really cool too.  Very nice picture even though I don''t think its really good for this challenge.  Maybe an allusion to this being the spider''s home would''ve been a little more appropriate.  Great photo regardless!', '2003-05-30 15:48:26.000000', NULL, 1),
(310955, 22992, 3540, '<td valign="top">I''m a sucker for lines and geometry so this one got me right away.  I like the way you angled the "v" from the center to the left of the shot.  It''s a good shot and I also like the title too.  Nice work.</td>', 'I''m a sucker for lines and geometry so this one got me right away.  I like the way you angled the "v" from the center to the left of the shot.  It''s a good shot and I also like the title too.  Nice work.', '2003-05-30 15:52:24.000000', NULL, 1),
(310956, 22877, 3540, '<td valign="top">This is a pretty weird photo if you don''t mind me saying so.  I like the painting, but the photo  involves more than that.  I like the bright spot on the wall and the use of negative space to really accentuate the painting.  We are forced to look at it.  My feeling is that it will not do very well, but I think its better than average.  I really think you made the most of this bit of wall and the painting.  Good job</td>', 'This is a pretty weird photo if you don''t mind me saying so.  I like the painting, but the photo  involves more than that.  I like the bright spot on the wall and the use of negative space to really accentuate the painting.  We are forced to look at it.  My feeling is that it will not do very well, but I think its better than average.  I really think you made the most of this bit of wall and the painting.  Good job', '2003-05-30 15:54:54.000000', NULL, 1),
(310986, 22942, 7436, '<td valign="top">Different.  Interesting.  I''ll give bonus points just because it''s unique.</td>', 'Different.  Interesting.  I''ll give bonus points just because it''s unique.', '2003-05-30 17:06:30.000000', NULL, 1),
(310990, 22970, 7436, '<td valign="top">Ack!!  Someone get Mr. Clean!  <br/>As the Arby''s saying goes, "Different is good."  Keen pic.</td>', 'Ack!!  Someone get Mr. Clean!  As the Arby''s saying goes, "Different is good."  Keen pic.', '2003-05-30 17:07:48.000000', NULL, 1),
(310993, 23066, 7436, '<td valign="top">Maybe a little too much of a separation in the middle caused by the pole.  Also creates a tangent with the front of that house which separates even more.</td>', 'Maybe a little too much of a separation in the middle caused by the pole.  Also creates a tangent with the front of that house which separates even more.', '2003-05-30 17:18:06.000000', NULL, 1),
(310995, 22428, 7436, '<td valign="top">I like the symmetry and the LACK of symmetry.  The texture is very nice.</td>', 'I like the symmetry and the LACK of symmetry.  The texture is very nice.', '2003-05-30 17:18:42.000000', NULL, 1),
(310996, 22341, 7436, '<td valign="top">It''s interesting how this picture frames itself.  I wish the sky was behaving a little more for you.  I think that could jump this picture up a point or two.</td>', 'It''s interesting how this picture frames itself.  I wish the sky was behaving a little more for you.  I think that could jump this picture up a point or two.', '2003-05-30 17:19:27.000000', NULL, 1),
(311001, 22955, 7436, '<td valign="top">Eww.. gross.  But cool symmetry and use of black and white.</td>', 'Eww.. gross.  But cool symmetry and use of black and white.', '2003-05-30 17:21:40.000000', NULL, 1),
(311002, 22848, 7436, '<td valign="top">I like the story the picture tells and the light on the wheel, but the majority of the picture is just too dark for me.  Or maybe I''m going blind.</td>', 'I like the story the picture tells and the light on the wheel, but the majority of the picture is just too dark for me.  Or maybe I''m going blind.', '2003-05-30 17:23:21.000000', NULL, 1),
(311005, 23068, 7436, '<td valign="top">Show off.  Err.. I mean.. nice place.</td>', 'Show off.  Err.. I mean.. nice place.', '2003-05-30 17:24:03.000000', NULL, 1),
(311008, 22622, 7436, '<td valign="top">The clouds are so awesome.. it makes me wonder how this would have looked in color.</td>', 'The clouds are so awesome.. it makes me wonder how this would have looked in color.', '2003-05-30 17:25:06.000000', NULL, 1),
(311010, 23079, 7436, '<td valign="top">Nice blue in the sky.  Nice use of thirds.  Not so interesting though.</td>', 'Nice blue in the sky.  Nice use of thirds.  Not so interesting though.', '2003-05-30 17:25:46.000000', NULL, 1),
(311012, 22999, 7436, '<td valign="top">Nice color.  It looks a bit fuzzy to me though.</td>', 'Nice color.  It looks a bit fuzzy to me though.', '2003-05-30 17:26:59.000000', NULL, 1),
(311015, 22789, 7436, '<td valign="top">I think a little more contrast would give those colors some more punch.  Of course.. it might just be that there is a great amount of contrast between your picture and your border.</td>', 'I think a little more contrast would give those colors some more punch.  Of course.. it might just be that there is a great amount of contrast between your picture and your border.', '2003-05-30 17:29:50.000000', NULL, 1),
(311017, 22262, 7436, '<td valign="top">What can I say?  I''m a sucker for black and white .. and repetition.  Me likey.</td>', 'What can I say?  I''m a sucker for black and white .. and repetition.  Me likey.', '2003-05-30 17:31:03.000000', NULL, 1),
(311019, 23055, 7436, '<td valign="top">I am confused.  If this was a digital photograph, why not try to take it again when you found out that it was so fuzzy?  The lower-side lighting is also quite harsh.</td>', 'I am confused.  If this was a digital photograph, why not try to take it again when you found out that it was so fuzzy?  The lower-side lighting is also quite harsh.', '2003-05-30 17:32:23.000000', NULL, 1),
(311022, 22255, 7436, '<td valign="top">Was the fuzziness of the picture intentional?  It was a digital shot, right?  Why not try to take it again when you saw the image was blurry?</td>', 'Was the fuzziness of the picture intentional?  It was a digital shot, right?  Why not try to take it again when you saw the image was blurry?', '2003-05-30 17:33:36.000000', NULL, 1),
(311023, 23059, 3102, '<td valign="top">I can see what you were going for here, but I think it needed to be executed a little better overall.  It''s hard to pick out the ant, and the overall image is a bit blurry.</td>', 'I can see what you were going for here, but I think it needed to be executed a little better overall.  It''s hard to pick out the ant, and the overall image is a bit blurry.', '2003-05-30 17:34:05.000000', NULL, 1),
(311024, 23059, 7436, '<td valign="top">Interesting idea.  Not so great execution.  I would try a different angle.. and certainly make sure it is in focus.</td>', 'Interesting idea.  Not so great execution.  I would try a different angle.. and certainly make sure it is in focus.', '2003-05-30 17:34:21.000000', NULL, 1),
(311025, 22992, 7436, '<td valign="top">My eyes are wiggin'' out!!  Good use of diagonals with horizontals.</td>', 'My eyes are wiggin'' out!!  Good use of diagonals with horizontals.', '2003-05-30 17:34:57.000000', NULL, 1),
(311027, 22916, 3102, '<td valign="top">The image itself is a bit too small to make a real good judgement... but it seems like it''s "just a picture of a cat" without a lot of compelling artistic qualities, I''m afraid.</td>', 'The image itself is a bit too small to make a real good judgement... but it seems like it''s "just a picture of a cat" without a lot of compelling artistic qualities, I''m afraid.', '2003-05-30 17:35:26.000000', NULL, 1),
(311028, 22501, 7436, '<td valign="top">Show off.  Yes.  That''s my envy talking.  Cool place.</td>', 'Show off.  Yes.  That''s my envy talking.  Cool place.', '2003-05-30 17:35:34.000000', NULL, 1),
(311029, 22986, 7436, '<td valign="top">You even gave it a bath.  I like how the chrome looks.  Still not sure how much I like the picture overall though.</td>', 'You even gave it a bath.  I like how the chrome looks.  Still not sure how much I like the picture overall though.', '2003-05-30 17:36:52.000000', NULL, 1),
(311030, 22978, 3102, '<td valign="top">The composition just seems a bit off on this one... it''s not really clear what the specific subject is, not to mention that the angle feels uncomfortable.  I guess the main issue is that I "don''t know why I''m looking at this."  It seems to me like you simply photographed an arbitrary portion of the house.</td>', 'The composition just seems a bit off on this one... it''s not really clear what the specific subject is, not to mention that the angle feels uncomfortable.  I guess the main issue is that I "don''t know why I''m looking at this."  It seems to me like you simply photographed an arbitrary portion of the house.', '2003-05-30 17:37:56.000000', NULL, 1),
(311031, 23028, 7436, '<td valign="top">You call that home?  I mean.. it''s a decent picture of flowers, but that''s what you''d call home?  Guess there isn''t enough context for me.</td>', 'You call that home?  I mean.. it''s a decent picture of flowers, but that''s what you''d call home?  Guess there isn''t enough context for me.', '2003-05-30 17:38:47.000000', NULL, 1),
(311032, 22991, 3102, '<td valign="top">Well...... it''s indeed home, I suppose.  But I have to be honest in saying that it doesn''t appear that there was a lot of thought put into this one.  It just looks as though you suddenly remembered that you wanted to submit a shot, and this was the first thing you saw.  Sorry...</td>', 'Well...... it''s indeed home, I suppose.  But I have to be honest in saying that it doesn''t appear that there was a lot of thought put into this one.  It just looks as though you suddenly remembered that you wanted to submit a shot, and this was the first thing you saw.  Sorry...', '2003-05-30 17:39:37.000000', NULL, 1),
(311033, 22958, 7436, '<td valign="top">Cute.  AND scary.  Maybe it''s a sign that you should call some place ELSE home.  I doubt you would fit in there anyway... especially with your camera.  And if you had no camera, how fun would home be anyway?<br/> <br/>However, I like the pic.  It''s keen.</td>', 'Cute.  AND scary.  Maybe it''s a sign that you should call some place ELSE home.  I doubt you would fit in there anyway... especially with your camera.  And if you had no camera, how fun would home be anyway? However, I like the pic.  It''s keen.', '2003-05-30 17:40:07.000000', NULL, 1),
(311037, 22823, 8713, '<td valign="top">Not bad. The color seems to be a little too saturated.</td>', 'Not bad. The color seems to be a little too saturated.', '2003-05-30 17:42:01.000000', NULL, 1),
