(312745, 23027, 6696, '<td valign="top">Very nice.  I really like the contrast, dof, and overall composition of this shot.  Not the typical pet shot.  7</td>', 'Very nice.  I really like the contrast, dof, and overall composition of this shot.  Not the typical pet shot.  7', '2003-06-02 13:34:55.000000', NULL, 1),
