(313382, 22929, 5822, '<td valign="top">I find the colors a little too saturated so much that they obsucre the interesting objects in the scene, but I like this photo and think it''s very interesting. to look at. It''s got an exotic look</td>', 'I find the colors a little too saturated so much that they obsucre the interesting objects in the scene, but I like this photo and think it''s very interesting. to look at. It''s got an exotic look', '2003-06-02 21:57:55.000000', NULL, 1),
(313387, 22624, 8416, '<td valign="top">i love this photo.the lighting is so soft.great job!</td>', 'i love this photo.the lighting is so soft.great job!', '2003-06-02 22:07:00.000000', NULL, 1),
(313390, 22888, 8416, '<td valign="top">very creative!</td>', 'very creative!', '2003-06-02 22:10:13.000000', NULL, 1),
(313392, 22968, 6325, '<td valign="top">Nice composition. The image gives that "Home Sweet Home Feel". I''m not crazy about the color processing.</td>', 'Nice composition. The image gives that "Home Sweet Home Feel". I''m not crazy about the color processing.', '2003-06-02 22:14:31.000000', NULL, 1),
(313393, 22508, 2158, '<td valign="top">That ornament with the cut off head really spoils this shot.</td>', 'That ornament with the cut off head really spoils this shot.', '2003-06-02 22:16:09.000000', NULL, 1),
(313396, 22452, 5822, '<td valign="top">Very creative idea</td>', 'Very creative idea', '2003-06-02 22:27:53.000000', NULL, 1),
