INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(313797, 23031, 7711, '<td valign="top">the sky is too white here to be so much of the shot. I think composition would be improved if you cropped some of that out, or waited until the sky was more interesting. :)</td>', 'the sky is too white here to be so much of the shot. I think composition would be improved if you cropped some of that out, or waited until the sky was more interesting. :)', '2003-06-03 13:29:12.000000', NULL, 1),
(313798, 22945, 9089, '<td valign="top">Too many things trying to get my attention.</td>', 'Too many things trying to get my attention.', '2003-06-03 13:30:18.000000', NULL, 1),
(313799, 22508, 7711, '<td valign="top">oh that''s SO cute. Ok, you win, you melted me with this shot. I love that he''s biting the flowers. Nice perspective.</td>', 'oh that''s SO cute. Ok, you win, you melted me with this shot. I love that he''s biting the flowers. Nice perspective.', '2003-06-03 13:32:17.000000', NULL, 1),
(313801, 22948, 8860, '<td valign="top">I bet your camera cost more than this building  and you''ve done a great job with it!</td>', 'I bet your camera cost more than this building  and you''ve done a great job with it!', '2003-06-03 13:33:02.000000', NULL, 1),
(313803, 22946, 7711, '<td valign="top">this is the most perfect interpretation of the challenge. :) I love the excited looks on all the children''s faces, the little bag of snacks, and the interested and involved look of david. ;) Might have benefitted from a bit softer light, maybe tungsten light yellow cast? :) I don''t know, but you still got my 10.</td>', 'this is the most perfect interpretation of the challenge. :) I love the excited looks on all the children''s faces, the little bag of snacks, and the interested and involved look of david. ;) Might have benefitted from a bit softer light, maybe tungsten light yellow cast? :) I don''t know, but you still got my 10.', '2003-06-03 13:35:35.000000', NULL, 1),
(313804, 22621, 8860, '<td valign="top">This is why photography was invented. Excellent.</td>', 'This is why photography was invented. Excellent.', '2003-06-03 13:35:43.000000', NULL, 1),
(313805, 22774, 8860, '<td valign="top">I could feel very at home here - surrounded by redwoods - I can almost smell the freshness. What a lovely place and all credit to the shot for getting that across.</td>', 'I could feel very at home here - surrounded by redwoods - I can almost smell the freshness. What a lovely place and all credit to the shot for getting that across.', '2003-06-03 13:37:46.000000', NULL, 1),
(313807, 22912, 7711, '<td valign="top">I find this shot a bit stark and without emotion. I don''t get a feeling of home as much as I feel like its a sterile asylum. <br/> <br/>edit to add: I do think it is an interesting with the lines of the light.</td>', 'I find this shot a bit stark and without emotion. I don''t get a feeling of home as much as I feel like its a sterile asylum.  edit to add: I do think it is an interesting with the lines of the light.', '2003-06-03 13:41:56.000000', NULL, 1),
(313808, 23070, 8860, '<td valign="top">Beautiful, thought-evoking shot.</td>', 'Beautiful, thought-evoking shot.', '2003-06-03 13:42:20.000000', NULL, 1),
(313809, 23058, 9089, '<td valign="top">hmmmmm......</td>', 'hmmmmm......', '2003-06-03 13:43:38.000000', NULL, 1),
