(314510, 22891, 6900, '<td valign="top">It''s a good thing LAND appreciates in value cuz this house sure didn''t!  8</td>', 'It''s a good thing LAND appreciates in value cuz this house sure didn''t!  8', '2003-06-04 00:55:03.000000', NULL, 1),
(314511, 22847, 7778, '<td valign="top">A bit topically ''strained'', which is a shame, coz it''s otherwise a fun shot with good lighting and composition. The range of blue in the smaller balloon is a little feast!</td>', 'A bit topically ''strained'', which is a shame, coz it''s otherwise a fun shot with good lighting and composition. The range of blue in the smaller balloon is a little feast!', '2003-06-04 00:55:31.000000', NULL, 1),
